CREATE OR REPLACE FUNCTION app.global_elements_readiness_defect(p_site_id uuid, p_kind global_element_kind, p_content jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE problem text; component jsonb; values jsonb; candidate text;
BEGIN
  problem := app.global_elements_readiness_before_frame_documents(p_site_id,p_kind,p_content);
  IF problem IS NOT NULL THEN RETURN problem; END IF;
  IF p_content->'schemaVersion' IS DISTINCT FROM '2'::jsonb OR p_content->'enabled'='false'::jsonb THEN RETURN NULL; END IF;
  component := app.global_component_view(p_site_id,p_kind,p_content);
  IF component IS NULL THEN RETURN format('the %s component is unavailable',p_kind); END IF;
  values := p_content->'component'->'values';

  -- Match the same anchored local path and UUID contract as collection PDF
  -- links. Static HTML, typed links and rich text share delivery's exact sink
  -- parser; external URLs, image sources and inert metadata remain excluded.
  IF app.frame_component_uses_url_pattern(component,values,
    '^/assets/(?![0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}([?#][^[:space:]]*)?$)',true) THEN
    RETURN format('the %s contains an invalid document address',p_kind);
  END IF;
  FOR candidate IN SELECT DISTINCT lower(match[1]) FROM regexp_matches(
    jsonb_build_object('definition',component,'values',values)::text,
    '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})','g') AS matches(match)
  LOOP
    IF app.frame_component_uses_url_pattern(component,values,
      '^/assets/'||candidate||'([?#][^[:space:]]*)?$',true)
      AND NOT EXISTS(SELECT 1 FROM public.site_assets a
        WHERE a.id=candidate::uuid AND a.site_id=p_site_id AND a.kind='document') THEN
      RETURN format('the %s contains a document that is missing, is not a PDF, or belongs to another site',p_kind);
    END IF;
  END LOOP;
  RETURN NULL;
END
$function$
